sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '' || g_form.getValue("trainning_date") === '') {
        return;
    }

    let [day, month, year] = g_form.getValue("trainning_date").split("/");
    let dateInQuestion = `${year}-${month}-${day}`;

	let gaSchedule = new GlideAjax("ServiceNow_School_Ajax");
	gaSchedule.addParam("sysparm_name", "findSubjectDate");
	gaSchedule.addParam("sysparm_trainning_date", dateInQuestion);
	gaSchedule.addParam("sysparm_class_subject", newValue);

	gaSchedule.getXMLAnswer(function(response){
		let objResponse = JSON.parse(response);
		if(objResponse.sys_id != null){
        	g_form.addErrorMessage(`There's already a class with this subject on this date! Check <a href="https://dev273945.service-now.com/nav_to.do?uri=x_1974925_servic_0_schedule.do?sys_id=${objResponse.sys_id}">${objResponse.number}</a> for information.`);
        	g_form.setValue("class_subject", "");
		}
		else {
        	g_form.clearMessages();
   		}
	})
}
